};

scwin.save = async function() {
    MxLogicalTr_bycorp.KeyName = "toinb_dataid4";

    const sbmOptions = {
        id : "sbm_MxLogicalTr_bycorp",
        action : "/bycorp.do",
        ref : "MxDataSet_bycorp",
        target : "MxLogicalTr_bycorp=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
};

scwin.saveChrgteam = async function() {
    MxLogicalTr_chrgteam.KeyName = "toinb_dataid4";

    const sbmOptions = {
        id : "sbm_MxLogicalTr_chrgteam",
        action : "/chrgteam.do",
        ref : "MxDataSet_charg_team",
        target : "MxLogicalTr_chrgteam=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
};

///////// 5. 일반/업무 함수 영역 /////////
scwin.insertSet = function(sval) {
    const chrg_cd = MxCombo_chrg_cd.getSelectedIndex() + 1;
    if (!scwin.cntDatasetRowCheck(sval)) {
        alert("적용할 체크사항이 없습니다.");
    } else {
        for (let i = sval.getRowCount() - 1; i >= 0; i--) {
            if (sval.getCellData(i, "CHK_FLAG") === 1) {
                // sval.DeleteRow(i);
                if (MxDataSet_bycorp.getCellData(i, "USR_ID") !== "") {
                    const text = confirm(MxDataSet_bycorp.getCellData(i, "COM_ABBRV") + '회사는 ' + MxDataSet_bycorp.getCellData(i, "EMP_NM") + '으로 지정되어 있습니다.\n변경하시겠습니까?');
                    if (text === true) {
                        MxDataSet_bycorp.setCellData(i, "USR_ID", txb_user_id.value);
                        MxDataSet_bycorp.setCellData(i, "EMP_NM", txb_user_name.value);
                        MxDataSet_bycorp.setCellData(i, "BYCORP_CHRG_BZ_TP_CD", chrg_cd);
                        MxDataSet_bycorp.setCellData(i, "ASSGN_STRT_DD", txb_start_day.text);
                        MxDataSet_bycorp.setCellData(i, "ASSGN_END_DD", txb_end_day.text);
                    } else {
                        return;
                    }
                } else {

                    // ********************************************************************
                    // [WebSquare 전환 추가] 원본 소스와 비교 필요
                    // 
                    // ********************************************************************

                    MxDataSet_bycorp.setCellData(i, "USR_ID", txb_user_id.value);
                    MxDataSet_bycorp.setCellData(i, "EMP_NM", txb_user_name.value);
                    MxDataSet_bycorp.setCellData(i, "BYCORP_CHRG_BZ_TP_CD", chrg_cd);
                    MxDataSet_bycorp.setCellData(i, "ASSGN_STRT_DD", txb_start_day.text);
                    MxDataSet_bycorp.setCellData(i, "ASSGN_END_DD", txb_end_day.text); /*ORG SRC: MxDataSet_bycorp.UserStatus(i) = "1";*/ X = "1";
                    MxDataSet_charg_team.insertRow();
                    // var cRow = MxDataSet_charg_team.RowPosition;
                    MxDataSet_charg_team.setCellData(MxDataSet_charg_team.getFocusedRowIndex(), "DEP_CD", txb_user_dep.value);
                    MxDataSet_charg_team.setCellData(MxDataSet_charg_team.getFocusedRowIndex(), "FORMISUR_CD", MxDataSet_bycorp.getCellData(i, "ISUR_CD"));
                    MxDataSet_charg_team.setCellData(MxDataSet_charg_team.getFocusedRowIndex(), "ASSGN_END_DD", MxDataSet_bycorp.getCellData(i, "ASSGN_END_DD"));
                    MxDataSet_charg_team.setCellData(MxDataSet_charg_team.getFocusedRowIndex(), "ASSGN_STRT_DD", MxDataSet_bycorp.getCellData(i, "ASSGN_STRT_DD"));
                    MxDataSet_charg_team.setCellData(MxDataSet_charg_team.getFocusedRowIndex(), "REMK", MxDataSet_bycorp.getCellData(i, "REMK"));
                    MxDataSet_charg_team.setCellData(MxDataSet_charg_team.getFocusedRowIndex(), "COM_ABBRV", MxDataSet_bycorp.getCellData(i, "COM_ABBRV"));
                }
            }
        }
    }
};

scwin.chgRep = function() {
    for (i = 1; i <= scwin.jv_bycorp_cnt; i++) {
        if (MxDataSet_bycorp.getCellData(i, "DEP_CD") === scwin.jv_dep_cd) {
            // sval.DeleteRow(i);

        }
    }
    // chg_funtion 처리

};

scwin.delete = function(sval) {
    if (txb_user_dep.value !== MxDataSet_charg_team.getCellData(0, "DEP_CD")) {
        alert("소속팀을 지정하십시요. 삭제는 동일한 소속팀이 지정되었을 경우에만 가능합니다.");
        return;
    }
    if (!scwin.cntDatasetRowCheck(sval)) {
        alert("체크사항이 없습니다.");
    } else {
        for (let i = sval.getRowCount() - 1; i >= 0; i--) {
            if (sval.getCellData(i, "CHK_FLAG") === 1 && txb_user_dep.value === MxDataSet_bycorp.getCellData(i, "DEP_CD")) {
                const del_Target = MxDataSet_bycorp.getCellData(i, "ISUR_CD");
                sval.removeRow(i);
                for (j = MxDataSet_charg_team.getRowCount(); j > 0; j--) {
                    // for(j=1; j<=MxDataSet_charg_team.countrow; j++){
                    if (MxDataSet_charg_team.getCellData(j, "FORMISUR_CD") === del_Target) {
                        MxDataSet_charg_team.removeRow(j + 1);
                    }
                }
            } else if (sval.getCellData(i, "CHK_FLAG") === 1 && txb_user_dep.value !== MxDataSet_bycorp.getCellData(i, "DEP_CD")) {
                alert(MxDataSet_bycorp.getCellData(i, "COM_ABBRV") + "는 " + txb_user_dep_nm.value + "의 담당이 아닙니다.");
            }
        }
    }
};

scwin.undo = function(sval) {
    sval.undoAll();
};

scwin.cnt = function() {
    // alert(MxDataSet_menu_data.CountRow);

};

scwin.cntDatasetRowCheck = function(sval) {
    // 데이터셋의 체크박스 선택이 되어 있는지 확인하여 참,거짓을 넘겨준다.
    cCnt = 0;
    for (let i = 0; i < sval.getRowCount(); i++) {
        // alert(sval.NameValue(i, "CHK_FLAG"));
        if (sval.getCellData(i, "CHK_FLAG") === 1) {
            cCnt++;
        }
    }
    if (cCnt === 0) {
        return false;
    } else {
        return true;
    }
};

scwin.upDep = function(row) {
    txb_user_updepnm.setValue("");
    let sval2 = MxDataSet_dep.getCellData(row, "UP_DEP_CD");
    const level_val = MxDataSet_dep.getCellData(row, "LEVEL_CD");

    let tRow = $c.data.getMatchedJSON(MxDataSet_dep, "DEP_CD", sval2);
    if (level_val === 3) {
        sval2 = MxDataSet_dep.getCellData(tRow, "UP_DEP_CD");

        tRow = $c.data.getMatchedJSON(MxDataSet_dep, "DEP_CD", sval2);
        txb_user_updepnm.setValue(MxDataSet_dep.getCellData(tRow, "DEP_NM"));
    } else {
        txb_user_updepnm.setValue(MxDataSet_dep.getCellData(tRow, "DEP_NM"));
    }
};

scwin.jongmokSearch = function() {
    MxDataSet_bycorp.sort("+COM_ABBRV", 0);
    MxDataSet_bycorp.sort('', 0);
    let cnt = 0;
    const len = txb_search_nm.getValue().length;
    const txtVal = txb_search_nm.getValue().toUpperCase();
    for (let i = 0; i < MxDataSet_bycorp.getRowCount(); i++) {
        const name = MxDataSet_bycorp.getCellData(i, "COM_ABBRV").substring(0, len).toUpperCase();
        if (txtVal <= name) {
            cnt = i;
            break;
        }
    }
    // grd_isu.Redraw ="true";
    // alert(txtVal);
    // alert(cnt);
    MxDataSet_bycorp.setFocusedCell(cnt, 0);

    grd_isu.focus();
};

scwin.gform_onload = async function() {
    const sbmOptions = {
        id : "sbm_MxDataSet_bycorp",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSet_bycorp=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    scwin.MxDataSet_bycorp_OnLoadCompleted(sbmRtn); // 구 콜백 연결

    const sbmOptions2 = {
        id : "sbm_MxDataSet_dep",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSet_dep=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);

    const sbmOptions3 = {
        id : "sbm_MxDataSet_charg_team",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSet_charg_team=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
    scwin.MxDataSet_charg_team_OnLoadCompleted(sbmRtn3); // 구 콜백 연결

    scwin.listDepSync();
    scwin.listBycorpSync();
    txb_start_day.setValue(scwin.jv_today);
};
